var _SLATE_EMBED_CSS=":host{display:block;margin:1em 0;color:var(--text);line-height:1.6;}:host([hidden]){display:none;}*{box-sizing:border-box;}.exp-md{margin:14px 0;} .exp-md h1{font-size:1.6rem;border-bottom:1px solid var(--border);padding-bottom:.2em;}\n.exp-figcap{margin:2px 24px 16px;font-size:.85rem;color:var(--dim);line-height:1.5;}\n.exp-figcap b{color:var(--text);}.exp-figcap p{display:inline;margin:0;}\n.exp-chart{margin:14px 0;}\n.exp-refs{margin-top:28px;border-top:1px solid var(--border);padding-top:8px;font-size:.9rem;}\n.exp-refs h2{font-size:1.1rem;}\n.exp-reflist{margin:6px 0 0;padding-left:1.6em;}.exp-reflist li{margin:3px 0;}\n.exp-reflist li:target{background:color-mix(in srgb,var(--accent) 16%,transparent);border-radius:4px;}\n/* Regular markdown links — accent-toned with a soft underline (parity with the live notebook's `.md a`),\n   not the browser default dark blue. Emitted BEFORE `a.cite`/`a.figref` so those keep their own style. */\n.exp-md a{color:var(--accent);text-decoration:none;border-bottom:1px solid color-mix(in srgb,var(--accent) 38%,transparent);transition:color .12s,border-color .12s;}\n.exp-md a:hover{color:color-mix(in srgb,var(--accent) 78%,var(--text));border-bottom-color:var(--accent);}\na.cite{color:var(--accent);text-decoration:none;}a.cite:hover{text-decoration:underline;}\n.exp-md table,.exp-table{border-collapse:collapse;margin:8px 0;font-size:.84rem;}\n.exp-md td,.exp-md th,.exp-table td,.exp-table th{border:1px solid var(--border);padding:4px 10px;text-align:left;}\n.exp-table th{background:var(--bg3);color:var(--dim);} .exp-table td.num{font-variant-numeric:tabular-nums;}\n/* per-column alignment (from ColumnDef.align) — after the base rule so an override wins */\n.exp-table td.align-right,.exp-table th.align-right{text-align:right;}\n.exp-table td.align-center,.exp-table th.align-center{text-align:center;}\n.exp-table tbody tr:nth-child(even){background:rgba(127,127,127,.06);}\n/* interactive enhancer (hydrated client-side): sortable headers, filter, paging, CSV */\n/* Centred, and scrollable when the table is wider than the column. `max-width` alone clamps the BOX\n   without giving the overflow anywhere to go, so a wide table just spilled past the page edge with no\n   way to reach the far columns. The live table has carried the other half of this rule all along\n   (`.slatetable .st-scroll`, notebook.css) — the export sheet is separate and only had the clamp. */\n.exp-tblwrap{width:fit-content;max-width:100%;margin:10px auto;overflow-x:auto;}\n.exp-table th{cursor:pointer;user-select:none;} .exp-table th::after{content:attr(data-arr);color:var(--accent);}\n.exp-tbl-bar{display:flex;align-items:center;gap:10px;margin-bottom:4px;}\n.exp-tbl-filter{background:var(--bg3);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:3px 8px;font-size:.78rem;min-width:150px;}\n.exp-tbl-filter:focus{outline:none;border-color:var(--accent);}\n.exp-tbl-info{color:var(--dim);font-size:.74rem;}\n.exp-tbl-csv,.exp-tbl-pg button{background:var(--bg3);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:2px 9px;font-size:.74rem;cursor:pointer;font-family:inherit;}\n.exp-tbl-csv{margin-left:auto;} .exp-tbl-csv:hover,.exp-tbl-pg button:hover{border-color:var(--accent);}\n.exp-tbl-pg{display:flex;align-items:center;gap:8px;margin-top:4px;} .exp-tbl-pg span{color:var(--dim);font-size:.74rem;}\n.exp-tbl-page{cursor:pointer;} .exp-tbl-page:hover{color:var(--accent);}\n.exp-tbl-goto{width:3.6em;background:var(--bg3);color:var(--text);border:1px solid var(--accent);border-radius:5px;padding:1px 5px;font-size:.74rem;font-family:inherit;}\n.exp-tblnote{color:var(--dim);font-size:.74rem;margin-top:3px;font-style:italic;}\n.exp-md code{background:var(--bg3);padding:1px 5px;border-radius:4px;}\n/* A `---` in prose — themed, or the browser's `1px inset grey` shows through (mirrors `.md hr`). */\n.exp-md hr{border:none;border-top:1px solid var(--border);margin:1.4em 0;}\n/* Admonitions (`!!! category \"Title\"`). The live page styles these in notebook.css; the export has its\n   own sheet, so the rules are mirrored here or an exported page carries correct markup with nothing to\n   draw it — the callouts flatten into ordinary prose. Same shape as the live rules: a `--adm` accent the\n   box derives its tint, rule and title bar from, so an unrecognised category still looks deliberate.\n   The title leans on the palette's high-emphasis text (`--titlefg` here, `--strong` live) with only a\n   hint of accent, which is what keeps it legible on the light themes. */\n.exp-md .admonition{--adm:var(--dim);margin:1em 0;border-radius:7px;overflow:hidden;\n  border:1px solid color-mix(in srgb,var(--adm) 40%,var(--border));border-left:4px solid var(--adm);\n  background:color-mix(in srgb,var(--adm) 7%,var(--bg2));}\n.exp-md .admonition>.admonition-title{margin:0;padding:6px 14px;font-weight:600;letter-spacing:.01em;\n  color:color-mix(in srgb,var(--adm) 25%,var(--titlefg));\n  background:color-mix(in srgb,var(--adm) 15%,var(--bg3));\n  border-bottom:1px solid color-mix(in srgb,var(--adm) 28%,var(--border));}\n.exp-md .admonition>:not(.admonition-title){margin-left:14px;margin-right:14px;}\n.exp-md .admonition>.admonition-title+*{margin-top:10px;}\n.exp-md .admonition>:last-child{margin-bottom:10px;}\n.exp-md .admonition code{background:color-mix(in srgb,var(--adm) 10%,var(--bg3));}\n.exp-md .admonition.note,.exp-md .admonition.info{--adm:var(--accent);}\n.exp-md .admonition.tip,.exp-md .admonition.hint,\n.exp-md .admonition.answer,.exp-md .admonition.solution{--adm:var(--green);}\n.exp-md .admonition.warning,.exp-md .admonition.caution{--adm:var(--gold);}\n.exp-md .admonition.danger,.exp-md .admonition.error,.exp-md .admonition.compat{--adm:var(--red);}\n/* A NamedTuple value rendered as a RECORD (record_display.jl). Mirrored from notebook.css for the\n   same reason as the admonitions above: the export sheet is separate, so without these an exported\n   page carries correct record markup with nothing to draw it — the field cards collapse into a run\n   of bare text. `--val` and `--ovl` are live-sheet colours the export palette does not define, so\n   each use carries a fallback rather than the palettes growing two entries for one component.\n   The matrix thumbnails' click-to-expand is live-only (it needs the notebook's JS), so the overlay\n   rules are not mirrored — a thumbnail exports as the static image it already is. */\n.exp-out .slate-record{margin:4px 0;}\n.exp-out .srec-grid{display:flex;flex-wrap:wrap;gap:6px;align-items:stretch;}\n.exp-out .srec-f{display:flex;flex-direction:column;justify-content:flex-start;gap:0;min-width:0;\n  max-width:100%;padding:0;border-radius:7px;background:var(--bg2);border:1px solid var(--border);overflow:hidden;}\n.exp-out .srec-k{display:block;font-size:.66rem;color:var(--dim);letter-spacing:.03em;white-space:nowrap;\n  padding:3px 10px;background:var(--bg);border-bottom:1px solid var(--border);}\n.exp-out .srec-f>:not(.srec-k){margin:5px 10px 6px;}\n.exp-out .srec-v{font-family:'Cascadia Code','Fira Code',monospace;font-size:.88rem;\n  color:var(--val,var(--text));white-space:nowrap;font-variant-numeric:tabular-nums;}\n.exp-out .srec-err{font-size:.74rem;color:var(--dim);}\n.exp-out .srec-u{margin-left:5px;font-size:.76rem;color:var(--dim);}\n.exp-out .srec-bool.yes{color:var(--green);} .exp-out .srec-bool.no{color:var(--red);}\n.exp-out .srec-str,.exp-out .srec-text{color:var(--text);white-space:normal;overflow-wrap:anywhere;font-size:.82rem;}\n/* A nested tuple groups by a rule down the left rather than a box, so it cannot be mistaken for a cell. */\n.exp-out .srec-nest{flex-basis:100%;padding:2px 0 3px 10px;border-radius:0;background:transparent;\n  border:none;border-left:2px solid var(--accent);}\n.exp-out .srec-nest>.srec-k{display:block;font-size:.66rem;color:var(--accent);font-weight:600;padding:0;\n  margin-bottom:4px;letter-spacing:.06em;text-transform:uppercase;opacity:.75;background:transparent;border-bottom:none;}\n.exp-out .srec-nest>:not(.srec-k){margin:0;}\n.exp-out .srec-nest .srec-nest{border-left-color:var(--dim);}\n.exp-out .srec-nest .srec-nest>.srec-k{color:var(--dim);}\n.exp-out .srec-rich>*{margin:0;}\n.exp-out .srec-more{align-self:center;color:var(--dim);font-size:.74rem;}\n.exp-out .srec-mat{display:flex;flex-direction:column;align-items:center;gap:3px;}\n.exp-out .srec-mat-svg{display:block;border-radius:2px;border:1px solid var(--border);}\n.exp-out .srec-mat-cap{font-family:'Cascadia Code','Fira Code',monospace;font-size:.68rem;color:var(--dim);white-space:nowrap;}\n/* Record vs plain text. The preference is a class on the body, which is why it survives into a\n   static export at all — no re-render and no round trip, so the toggle keeps working with no kernel. */\n.exp-out .srec-plain{display:none;margin:0;font-family:'Cascadia Code','Fira Code',monospace;\n  font-size:.84rem;color:var(--val,var(--text));white-space:pre-wrap;overflow-wrap:anywhere;}\nbody.record-plain .exp-out .slate-record>.srec-grid{display:none;}\nbody.record-plain .exp-out .srec-plain{display:block;}\n/* An image (or dropped clip) alone in its paragraph is a figure — centred. One inside a run of prose\n   stays inline. A `{width=…}`/`{align=…}` block writes an inline style, which outranks this. */\n.exp-md p>img:only-child,.exp-md p>video:only-child,.exp-md p>audio:only-child,\n.exp-figcap p>img:only-child{display:block;margin-inline:auto;max-width:100%;height:auto;}\n.exp-code{margin:14px 0;border:1px solid var(--border);border-radius:8px;background:var(--bg2);overflow:hidden;}\n/* Side-by-side cells (a `column=N` tag): equal-width flex columns, stacking on a narrow screen. */\n.exp-row{display:flex;gap:16px;align-items:flex-start;}\n.exp-row>section{flex:1 1 0;min-width:0;}\n@media(max-width:640px){.exp-row{flex-direction:column;}}\n.exp-src{margin:0;padding:10px 14px;background:var(--bg3);border-bottom:1px solid var(--border);overflow-x:auto;}\n.exp-src code{font-family:'Cascadia Code','Fira Code',monospace;font-size:.82rem;color:var(--text);white-space:pre;}\n.exp-src .hl-kw{color:var(--hl-kw);} .exp-src .hl-com{color:var(--hl-com);font-style:italic;} .exp-src .hl-num{color:var(--hl-num);} .exp-src .hl-str{color:var(--hl-str);} .exp-src .hl-macro{color:var(--hl-macro);} .exp-src .hl-op{color:var(--hl-op);} .exp-src .hl-fn{color:var(--hl-fn);} .exp-src .hl-type{color:var(--hl-type);} .exp-src .hl-sym{color:var(--hl-sym);}\n.exp-out{font-size:.86rem;} .exp-out .out,.exp-out .val,.exp-out .err{padding:8px 14px;}\n.exp-out .out{color:var(--dim);} .exp-out .val{color:var(--green);} .exp-out .err{color:var(--red);}\n/* ANSI colour in captured output — the same class names `_ansi_html` emits for the live page. This\n   sheet is separate from notebook.css, so without these an exported page would show base-16 colour\n   as plain text while 256/truecolour (inline styles) still came through: colour that half works.\n   The eight base colours map onto the export palette so they follow the chosen theme. */\n.ansi-fg-0,.ansi-fg-8{color:var(--dim);}      .ansi-bg-0,.ansi-bg-8{background:var(--dim);}\n.ansi-fg-1,.ansi-fg-9{color:var(--red);}      .ansi-bg-1,.ansi-bg-9{background:var(--red);}\n.ansi-fg-2,.ansi-fg-10{color:var(--green);}   .ansi-bg-2,.ansi-bg-10{background:var(--green);}\n.ansi-fg-3,.ansi-fg-11{color:var(--gold);}    .ansi-bg-3,.ansi-bg-11{background:var(--gold);}\n.ansi-fg-4,.ansi-fg-12{color:var(--accent);}  .ansi-bg-4,.ansi-bg-12{background:var(--accent);}\n.ansi-fg-5{color:#c678dd;} .ansi-fg-13{color:#d19aeb;}\n.ansi-bg-5{background:#c678dd;} .ansi-bg-13{background:#d19aeb;}\n.ansi-fg-6{color:#56b6c2;} .ansi-fg-14{color:#7fd4de;}\n.ansi-bg-6{background:#56b6c2;} .ansi-bg-14{background:#7fd4de;}\n.ansi-fg-7,.ansi-fg-15{color:var(--text);}    .ansi-bg-7,.ansi-bg-15{background:var(--text);}\n.ansi-bold{font-weight:600;} .ansi-dim{opacity:.72;} .ansi-italic{font-style:italic;}\n.ansi-underline{text-decoration:underline;} .ansi-strike{text-decoration:line-through;}\n.ansi-reverse{filter:invert(1);}\n.exp-out pre{margin:0;white-space:pre-wrap;} .exp-out .dispwrap,.disp.img{padding:10px 14px;}\n.disp.img img{max-width:100%;height:auto;border-radius:4px;display:block;}\n.disp.latex{padding:6px 14px;overflow-x:auto;} .katex{font-size:1.1em;}\n/* `@bind` controls in a frozen page. Disabled until the client finds shipped data it can drive them\n   with, so the dimmed state is the DEFAULT and an enabled control is the exception — a reader can tell\n   at a glance which knobs still do something. */\n.exp-ctls{display:flex;flex-wrap:wrap;gap:18px;align-items:center;padding:8px 14px;font-size:.86rem;}\n.exp-ctl{display:flex;align-items:center;gap:9px;color:var(--dim);}\n.exp-ctl-lbl{white-space:nowrap;}\n/* A plain slider draws its own track and thumb instead of trusting `accent-color`, which Safari\n   ignores on a range input: the control then renders as native chrome — a light grey track and a\n   white thumb — which on a dark page is the one element that visibly is not part of the document.\n   The range slider further down already draws its own, so without this the two sliders on the same\n   page do not even match each other. `.rsin` is excluded, being that pair. */\n.exp-ctl input[type=range]:not(.rsin){-webkit-appearance:none;appearance:none;width:210px;height:16px;\n  background:none;cursor:pointer;}\n.exp-ctl input[type=range]:not(.rsin)::-webkit-slider-runnable-track{height:4px;border-radius:2px;\n  background:var(--bg3);border:1px solid var(--border);}\n.exp-ctl input[type=range]:not(.rsin)::-moz-range-track{height:4px;border-radius:2px;\n  background:var(--bg3);border:1px solid var(--border);}\n.exp-ctl input[type=range]:not(.rsin)::-webkit-slider-thumb{-webkit-appearance:none;margin-top:-6px;\n  width:14px;height:14px;border-radius:50%;background:var(--text);border:2px solid var(--accent);\n  box-shadow:0 1px 3px rgba(0,0,0,.5);}\n.exp-ctl input[type=range]:not(.rsin)::-moz-range-thumb{width:14px;height:14px;border-radius:50%;\n  background:var(--text);border:2px solid var(--accent);box-shadow:0 1px 3px rgba(0,0,0,.5);}\n.exp-ctl input[type=range]:not(.rsin):focus{outline:none;}\n.exp-ctl input:disabled,.exp-ctl select:disabled{opacity:.45;cursor:not-allowed;}\n/* multicheck — a row of boxes, matching the live control rather than a modifier-click listbox */\n.exp-checkgroup{display:inline-flex;flex-wrap:wrap;align-items:center;gap:4px 12px;}\n.exp-checkgroup label{display:inline-flex;align-items:center;gap:5px;cursor:pointer;}\n.exp-checkgroup label:has(input:disabled){opacity:.45;cursor:not-allowed;}\n.exp-ctl-val{color:var(--text);font-variant-numeric:tabular-nums;min-width:2.5em;}\n.exp-ctl-frozen{color:var(--text);font-variant-numeric:tabular-nums;}\n/* A `<select>` with no rules is browser chrome — white box, black text — which on a dark page is\n   the one element that visibly is not part of the document. Themed to match the live control. */\n.exp-ctl select{-webkit-appearance:none;appearance:none;\n  background:var(--bg2) url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' fill='none' stroke='%238b949e' stroke-width='1.6' stroke-linecap='round'/></svg>\") no-repeat right 8px center;\n  background-size:10px 7px;color:var(--text);border:1px solid var(--border);border-radius:6px;\n  padding:3px 26px 3px 8px;font:inherit;font-size:.86rem;cursor:pointer;}\n.exp-ctl select:focus{outline:none;border-color:var(--accent);}\n.exp-ctl select[multiple]{background-image:none;padding:4px 8px;cursor:default;}\n.exp-ctl input[type=number]{background:var(--bg2);color:var(--text);border:1px solid var(--border);\n  border-radius:6px;padding:3px 8px;font:inherit;font-size:.86rem;width:5.5em;}\n/* A range slider: the SAME construction as the live widget (widget-rangeslider.js) — two native\n   inputs overlaid on one track with a filled span between the thumbs, so the pair reads as the one\n   interval it is. The inputs take no pointer events; only their thumbs do, which is the trick that\n   lets the upper one be grabbed through the lower. */\n.rsbox{position:relative;display:inline-block;width:190px;height:20px;}\n.rstrack{position:absolute;left:0;right:0;top:8px;height:4px;border-radius:2px;\n  background:var(--bg3);border:1px solid var(--border);}\n.rsfill{position:absolute;top:0;bottom:0;background:var(--accent);border-radius:2px;opacity:.85;}\n.rsin{position:absolute;left:0;top:0;width:100%;height:20px;margin:0;\n  -webkit-appearance:none;appearance:none;background:none;pointer-events:none;}\n.rsin:focus{outline:none;}\n.rsin::-webkit-slider-thumb{-webkit-appearance:none;pointer-events:auto;cursor:grab;\n  width:14px;height:14px;border-radius:50%;background:var(--text);border:2px solid var(--accent);\n  box-shadow:0 1px 3px rgba(0,0,0,.5);}\n.rsin::-webkit-slider-thumb:active{cursor:grabbing;}\n.rsin::-moz-range-thumb{pointer-events:auto;cursor:grab;\n  width:14px;height:14px;border-radius:50%;background:var(--text);border:2px solid var(--accent);\n  box-shadow:0 1px 3px rgba(0,0,0,.5);}\n.rsin::-moz-range-track{background:none;border:none;}\n/* The thumb is 14px wide and centred on the track's end, so at maximum it overhangs `.rsbox` by half\n   its width and eats the flex gap — the readout then starts underneath it. The margin is that overhang. */\n.rsval{color:var(--dim);font-size:.76rem;font-variant-numeric:tabular-nums;white-space:nowrap;\n  margin-left:8px;}\n/* Surfaced strips keep their authored columns: `controls=[freq,amp],phase` is two columns, the\n   first stacking two knobs. */\n.exp-ctlcol{display:flex;flex-direction:column;gap:6px;}\n/* `download_button` — the one control on a frozen page that still DOES something, so it had better\n   not be the one that looks unstyled. Same rules as the live `.dlbtn` (notebook.css); the export\n   carried the markup and the click handler but none of the appearance. */\n.dlbtn{display:inline-flex;align-items:center;gap:7px;text-decoration:none;cursor:pointer;\n  background:var(--bg3);color:var(--text);border:1px solid var(--border);border-radius:8px;\n  padding:6px 13px;font-size:.83rem;transition:border-color .12s, background .12s;}\n.dlbtn:hover{border-color:var(--accent);background:var(--bg2);color:var(--text);}\n.dlbtn .dlicon{color:var(--accent);font-size:.95rem;}\n/* A table select's rows ARE its control, so the whole thing renders and a click picks one. Disabled\n   until data lands, same as every other control — `data-off` is the flag the wiring toggles. */\n.exp-ts{max-height:230px;overflow:auto;border:1px solid var(--border);border-radius:6px;}\n.exp-ts table{border-collapse:collapse;width:100%;font-size:.82rem;}\n.exp-ts th{position:sticky;top:0;background:var(--bg2);text-align:left;padding:3px 8px;\n  border-bottom:1px solid var(--border);white-space:nowrap;}\n.exp-ts td{padding:2px 8px;border-bottom:1px solid var(--border);white-space:nowrap;}\n.exp-ts tbody tr{cursor:pointer;}\n.exp-ts tbody tr:hover{background:var(--bg3);}\n.exp-ts tbody tr.sel{background:var(--accent);color:var(--bg);}\n.exp-ctl [data-off=\"1\"],.exp-ctl.exp-ctl-wide [data-off=\"1\"]{opacity:.45;cursor:not-allowed;}\n.exp-ctl-wide{align-items:flex-start;flex-direction:column;gap:4px;width:100%;}\n@media print{ .exp-ctls{opacity:.7;} }\n@media print{ body{-webkit-print-color-adjust:exact;print-color-adjust:exact;} .exp-code{break-inside:avoid;} }\n.slate-embed{--bg2:color-mix(in srgb,var(--text) 4%,transparent);--bg3:color-mix(in srgb,var(--text) 8%,transparent);}.slate-embed>section.exp-code{margin:0;background:transparent;border-color:color-mix(in srgb,var(--text) 16%,transparent);}.slate-embed .exp-ctls{border-bottom:1px solid color-mix(in srgb,var(--text) 10%,transparent);}.slate-embed .exp-ctls:last-child{border-bottom:none;}.slate-embed>section.exp-md{margin:0;}.slate-embed-msg{padding:8px 12px;border:1px dashed var(--border);border-radius:6px;color:var(--dim);font-size:.85rem;}";
var _SLATE_BASE_TOKEN="__SLATE_BUNDLE_BASE__";
